# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::LocalEntry do
  it "derives reserved only from reservation rows of the entry's own company and never from entries.locked" do
    company_a = create(:company)
    company_b = create(:company)
    user = create(:user)
    create(:employment, company: company_a, user:)
    create(:employment, company: company_b, user:)
    project_a = create(:project, client: create(:client, company: company_a))
    project_b = create(:project, client: create(:client, company: company_b))
    fields = { user_id: user.id, work_date: Date.new(2026, 3, 2), duration: 60.0, bill_status: "unbilled" }

    provisional = described_class.create!(fields.merge(company_id: company_a.id, project_id: project_a.id, locked: false))
    committed = described_class.create!(fields.merge(company_id: company_a.id, project_id: project_a.id, locked: false))
    stale_flag = described_class.create!(fields.merge(company_id: company_a.id, project_id: project_a.id, locked: true))
    other_company = described_class.create!(fields.merge(company_id: company_b.id, project_id: project_b.id, locked: false))

    reserve = lambda do |company_id, entry_id, state|
      ActiveRecord::Base.connection.execute(ActiveRecord::Base.sanitize_sql_array([<<~SQL.squish, company_id, entry_id, state]))
        INSERT INTO reservations (company_id, entry_id, invoice_id, operation_id, state, disposition, created_at)
        VALUES (?, ?, 1, gen_random_uuid(), ?, 'active', now())
      SQL
    end
    # "`locked` is true when any reservation row, provisional or committed, exists for the entry in the same company."
    reserve.call(company_a.id, provisional.id, "provisional")
    reserve.call(company_a.id, committed.id, "committed")
    reserve.call(company_b.id, other_company.id, "committed")

    reserved = described_class.with_reserved.where(company_id: company_a.id).to_h { |entry| [entry.id, entry.reserved] }

    expect(reserved).to eq(provisional.id => true, committed.id => true, stale_flag.id => false)
  end
end
